    /// Spawn a command without shelling out to an external shell
    pub fn spawn_simple_command(&self, cwd: &str) -> Result<std::process::Command, ShellError> {
        let mut name_chars = self.name.item.chars();
        let name_edges = (name_chars.next(), name_chars.next_back());
        let trimmed_name = if matches!(
            name_edges,
            (Some('"'), Some('"')) | (Some('\''), Some('\'')) | (Some('`'), Some('`'))
        ) {
            name_chars.collect::<String>()
        } else {
            self.name.item.clone()
        };
        let head = nu_path::expand_to_real_path(trimmed_name)
            .to_string_lossy()
            .to_string();

        let mut process = std::process::Command::new(head);

        for (arg, arg_keep_raw) in self.args.iter().zip(self.arg_keep_raw.iter()) {
            let mut chars = arg.item.chars();
            let (trimmed_args, mut run_glob_expansion, mut keep_raw) =
                match (chars.next(), chars.next_back()) {
                    (Some('"'), Some('"')) => (chars.collect::<String>(), false, true),
                    (Some('\''), Some('\'')) => (chars.collect::<String>(), false, true),
                    (Some('`'), Some('`')) => (chars.collect::<String>(), true, false),
                    _ => (arg.item.clone(), true, false),
                };

            if *arg_keep_raw {
                keep_raw = true;
                run_glob_expansion = false;
            }

            let mut item = if keep_raw {
                trimmed_args
            } else {
                let mut quote_chars = trimmed_args.chars();
                match (quote_chars.next_back(), trimmed_args.contains('=')) {
                    (Some('"'), true) => quote_chars
                        .collect::<String>()
                        .replacen('"', "", 1)
                        .replace(r#"\""#, "\""),
                    (Some('\''), true) => quote_chars.collect::<String>().replacen('\'', "", 1),
                    _ => trimmed_args,
                }
            };

            if !keep_raw {
                item = nu_path::expand_tilde(item)
                    .to_string_lossy()
                    .to_string();
            }

            let cwd_path = PathBuf::from(cwd);
            if item.contains('*') && run_glob_expansion {
                let glob_chars: &[char] = &['*', '?', '['];
                let pattern_path = PathBuf::from(&item);
                let mut prefix_buf = PathBuf::new();
                let mut counter = 0;

                for component in pattern_path.components() {
                    if let std::path::Component::Normal(os) = component {
                        if os.to_string_lossy().contains(glob_chars) {
                            break;
                        }
                    }
                    prefix_buf.push(component);
                    counter += 1;
                }

                let mut just_pattern = PathBuf::new();
                let total_components = pattern_path.components().count();
                for idx in counter..total_components {
                    if let Some(comp) = pattern_path.components().nth(idx) {
                        just_pattern.push(comp);
                    }
                }

                let joined = if prefix_buf == Path::new(".") {
                    cwd_path.clone()
                } else if prefix_buf.to_string_lossy().as_ref().starts_with('~') {
                    prefix_buf
                } else {
                    cwd_path.join(prefix_buf)
                };

                let tilde_expanded = nu_path::expand_tilde(joined);
                let mut ndots_expanded = PathBuf::with_capacity(tilde_expanded.as_os_str().len());
                for component in nu_path::components(&tilde_expanded) {
                    match component {
                        std::path::Component::Normal(os)
                            if os.as_encoded_bytes().iter().all(|byte| *byte == b'.')
                                && os.len() >= 3 =>
                        {
                            let dots = os.len();
                            for _ in 0..dots - 1 {
                                ndots_expanded.push("..");
                            }
                        }
                        _ => ndots_expanded.push(component),
                    }
                }

                let expanded = nu_path::dots::expand_dots(ndots_expanded);

                let mut escaped = String::new();
                for ch in expanded.to_string_lossy().chars() {
                    if matches!(ch, '?' | '*' | '[' | ']') {
                        escaped.push('[');
                        escaped.push(ch);
                        escaped.push(']');
                    } else {
                        escaped.push(ch);
                    }
                }
                let glob_pattern_buf = PathBuf::from(escaped).join(just_pattern);
                let pattern = glob_pattern_buf.to_string_lossy().to_string();
                let glob_options = nu_glob::MatchOptions::default();

                if let Ok(glob) = nu_glob::glob_with(&pattern, glob_options) {
                    let matches: Vec<_> = glob.collect();
                    if matches.is_empty() {
                        process.arg(&item);
                    }
                    for entry in matches {
                        if let Ok(matched) = entry {
                            if let Ok(remainder) = matched.strip_prefix(&expanded) {
                                let new_prefix = diff_paths(&expanded, &cwd_path)
                                    .unwrap_or_else(|| expanded.clone());
                                process.arg(new_prefix.join(remainder).to_string_lossy().as_ref());
                            } else {
                                process.arg(matched.to_string_lossy().as_ref());
                            }
                        } else {
                            process.arg(&item);
                        }
                    }
                }
            } else {
                process.arg(&item);
            }
        }

        Ok(process)
    }

    /// Spawn a cmd command with `cmd /c args...`
    pub fn spawn_cmd_command(&self, cwd: &str) -> std::process::Command {
        let mut process = std::process::Command::new("cmd");

        // Disable AutoRun
        // TODO: There should be a config option to enable/disable this
        // Alternatively (even better) a config option to specify all the arguments to pass to cmd
        process.arg("/D");

        process.arg("/c");
        process.arg(&self.name.item);
        for (arg, arg_keep_raw) in self.args.iter().zip(self.arg_keep_raw.iter()) {
            // https://stackoverflow.com/questions/1200235/how-to-pass-a-quoted-pipe-character-to-cmd-exe
            // cmd.exe needs to have a caret to escape a pipe
            let arg = Spanned {
                item: arg.item.replace('|', "^|"),
                span: arg.span,
            };

            trim_expand_and_apply_arg(&mut process, &arg, arg_keep_raw, cwd)
        }

        process
    }
}

fn trim_expand_and_apply_arg(
    process: &mut CommandSys,
    arg: &Spanned<String>,
    arg_keep_raw: &bool,
    cwd: &str,
) {
    // if arg is quoted, like "aa", 'aa', `aa`, or:
    // if arg is a variable or String interpolation, like: $variable_name, $"($variable_name)"
    // `as_a_whole` will be true, so nu won't remove the inner quotes.
    let (trimmed_args, mut run_glob_expansion, mut keep_raw) = trim_enclosing_quotes(&arg.item);
    if *arg_keep_raw {
        keep_raw = true;
        // it's a list or a variable, don't run glob expansion either
        run_glob_expansion = false;
    }
    let mut arg = Spanned {
        item: if keep_raw {
            trimmed_args
        } else {
            remove_quotes(trimmed_args)
        },
        span: arg.span,
    };
    if !keep_raw {
        arg.item = nu_path::expand_tilde(arg.item)
            .to_string_lossy()
            .to_string();
    }
    let cwd = PathBuf::from(cwd);
    if arg.item.contains('*') && run_glob_expansion {
        // we need to run glob expansion, so it's NeedExpand.
        let path = Spanned {
            item: NuGlob::Expand(arg.item.clone()),
            span: arg.span,
        };
        if let Ok((prefix, matches)) = nu_engine::glob_from(&path, &cwd, arg.span, None) {
            let matches: Vec<_> = matches.collect();

            // FIXME: do we want to special-case this further? We might accidentally expand when they don't
            // intend to
            if matches.is_empty() {
                process.arg(&arg.item);
            }
            for m in matches {
                if let Ok(arg) = m {
                    let arg = if let Some(prefix) = &prefix {
                        if let Ok(remainder) = arg.strip_prefix(prefix) {
                            let new_prefix = if let Some(pfx) = diff_paths(prefix, &cwd) {
                                pfx
                            } else {
                                prefix.to_path_buf()
                            };

                            new_prefix.join(remainder).to_string_lossy().to_string()
                        } else {
                            arg.to_string_lossy().to_string()
                        }

